-- Insert Quiz Questions for Lesson: What Forms Do Inside LeadProspectrr

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 7 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 7 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'what-forms-do' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson what-forms-do not found in module 7';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main purpose of a form in LeadProspectrr?', 
    '["To collect data and end the interaction","To start the next action and trigger follow-up","To replace your website","To send spam emails"]'::jsonb,
    'To start the next action and trigger follow-up',
    'A form should start the next action, not end the interaction. It triggers follow-up processes like notifications, emails, and workflows.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
