-- Insert Quiz Questions for Lesson: When to Use a Form

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 7 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 7 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'when-to-use-forms' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson when-to-use-forms not found in module 7';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you use a form?', 
    '["Only for contact pages","When you need to collect information and send it into LeadProspectrr","Only for paid customers","Never, forms are outdated"]'::jsonb,
    'When you need to collect information and send it into LeadProspectrr',
    'Use a form whenever you need to collect information from someone and send it into LeadProspectrr for follow-up and organization.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you create different forms for different purposes?', 
    '["To make things more complicated","Different goals need different fields, tags, and follow-up processes","Forms are free so you should make many","It is required by law"]'::jsonb,
    'Different goals need different fields, tags, and follow-up processes',
    'Different forms allow you to capture the right information, apply appropriate tags, and trigger the correct follow-up for each specific purpose.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where do you find forms in LeadProspectrr?', 
    '["Settings → General","Sites → Forms","Contacts → Import","Dashboard → Widgets"]'::jsonb,
    'Sites → Forms',
    'Forms are found under Sites → Forms in LeadProspectrr, where you can view, create, edit, and manage all your forms.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


