-- Insert Quiz Questions for Lesson: What Makes a Good Lead Capture Form

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 7 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 7 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'good-lead-capture-form' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson good-lead-capture-form not found in module 7';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What makes a good lead capture form?', 
    '["Asking for as much information as possible","Being clear, short, and connected to the next step","Having 20+ fields","Using technical jargon"]'::jsonb,
    'Being clear, short, and connected to the next step',
    'A good form is clear, short, and connected to the next step. It asks only for what is needed to start a useful conversation.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What fields should you start with for most lead capture forms?', 
    '["Full address, company size, budget, website","First Name, Last Name, Email, Phone","Social security number, birth date, mother''s maiden name","Credit card number, expiration date, CVV"]'::jsonb,
    'First Name, Last Name, Email, Phone',
    'Start with the basics: First Name, Last Name, Email, Phone. Add one interest field to understand what they want.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why do long forms reduce responses?', 
    '["They look more professional","People are more likely to complete forms when they feel easy","Short forms cost more","Long forms load faster"]'::jsonb,
    'People are more likely to complete forms when they feel easy',
    'People abandon long, complex forms. Keep forms short and easy to maximize completion rates.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


