-- Insert Quiz Questions for Lesson: Button Text That Converts

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 7 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 7 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'button-text' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson button-text not found in module 7';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is ''Submit'' not the best button text?', 
    '["It is grammatically incorrect","It does not tell people what happens next","It is too long","It is not allowed"]'::jsonb,
    'It does not tell people what happens next',
    '''Submit'' is vague. Better button text tells people exactly what action they are taking and what happens next.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a good button text for a consultation form?', 
    '["Submit","Request My Call","Click Here","Go"]'::jsonb,
    'Request My Call',
    '''Request My Call'' clearly tells the person what they are doing and what happens next—requesting a call.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should button text do?', 
    '["Be as short as possible","Match the purpose of the form and tell people what happens next","Use technical language","Be mysterious"]'::jsonb,
    'Match the purpose of the form and tell people what happens next',
    'Button text should match the form''s purpose and clearly communicate what action the person is taking and what happens next.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


