-- Insert Quiz Questions for Lesson: What Happens After Submit

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 7 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 7 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'what-happens-after-submit' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson what-happens-after-submit not found in module 7';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should happen after someone submits a form?', 
    '["Nothing, the form just stores the data","Contact creation, tagging, notifications, thank-you emails, pipeline entry, and workflows","Delete the submission","Send a bill"]'::jsonb,
    'Contact creation, tagging, notifications, thank-you emails, pipeline entry, and workflows',
    'After form submission, LeadProspectrr can create contacts, add tags, send notifications and emails, add to pipelines, start workflows, and redirect to next steps.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you add a tag when someone submits a form?', 
    '["Tags are required by law","To organize leads by interest and know where they came from","To delete the lead later","To charge them money"]'::jsonb,
    'To organize leads by interest and know where they came from',
    'Tags help you organize leads by interest, track where they came from, and segment them for appropriate follow-up.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is a thank-you email important?', 
    '["It is required by law","People like to know their request was received and what happens next","It sells products immediately","It deletes the form submission"]'::jsonb,
    'People like to know their request was received and what happens next',
    'A thank-you email confirms the submission was received, sets expectations for follow-up, and starts building trust with the lead.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


