-- Insert Quiz Questions for Lesson: Common Mistakes to Avoid

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 7 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 7 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'common-mistakes-forms' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson common-mistakes-forms not found in module 7';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a common mistake when creating forms?', 
    '["Making forms too short","Asking for too much information","Using clear button text","Testing before publishing"]'::jsonb,
    'Asking for too much information',
    'A common mistake is asking for too much information. Long forms reduce completion rates. Ask only for what you truly need.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is not adding tags a mistake?', 
    '["Tags cost extra money","Without tags, it is harder to know where leads came from or what they wanted","Tags delete leads","Tags are required by law"]'::jsonb,
    'Without tags, it is harder to know where leads came from or what they wanted',
    'Without tags, you cannot easily segment leads, track their source, or trigger appropriate follow-up workflows.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What happens if you do not set up internal notifications?', 
    '["Leads are automatically deleted","The lead may be missed or sit unseen in the system","Forms load faster","Nothing happens"]'::jsonb,
    'The lead may be missed or sit unseen in the system',
    'Without notifications, you may not know when new leads come in, causing delays in follow-up or missed opportunities entirely.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


